const results = $input.first()?.json.results || [];
const triggerData = $('Execute Workflow Trigger').first()?.json || {};
const locale = triggerData.locale || 'ar';
const isAr = locale === 'ar';

if (results.length > 0 && results[0]) {
  const kb = results[0];
  const responseText = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
  const questionMatched = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);

  return [{
    json: {
      status: 'success',
      intent_handled: 'faq_query',
      category: kb.category,
      question_matched: questionMatched,
      reply: responseText,
      sources: ['MCIT Official Knowledge Base - ' + (kb.category || 'General')]
    }
  }];
} else {
  const defaultReply = isAr
    ? 'شكراً لتواصلك مع وزارة الاتصالات وتقنية المعلومات. يمكنك الاطلاع على خدماتنا ولوائحنا عبر المنصة الوطنية الموحدة. إذا كنت بحاجة لدعم إضافي، يمكنك طلب التحدث مع ممثل خدمة العملاء.'
    : 'Thank you for contacting the Ministry of Communications and Information Technology (MCIT). You may explore our initiatives and services on the national portal. If you need further assistance, please ask to speak with a human specialist.';

  return [{
    json: {
      status: 'fallback',
      intent_handled: 'faq_query',
      reply: triggerData.ai_output?.direct_response || defaultReply,
      sources: ['MCIT General Services Guidance']
    }
  }];
}
